import subprocess

def read_fasta(path):
    seqs={}; name=None
    with open(path) as f:
        for line in f:
            line=line.strip()
            if not line: continue
            if line.startswith('>'):
                name=line[1:].strip(); seqs[name]=''
            else:
                seqs[name]+=line
    return seqs

def comp(s):
    t={'A':'T','T':'A','G':'C','C':'G'}
    return ''.join(t[c] for c in s)
def revcomp(s):
    return comp(s)[::-1]

def oligotm(seq):
    r=subprocess.run(['oligotm','-tp','1','-sc','1','-mv','50','-dv','2','-n','0.8','-d','500',seq],
                     capture_output=True, text=True)
    return float(r.stdout.strip())

seqs=read_fasta('sequences.fasta')
