p=0
while inp[p]==out[p]: p+=1
I = out[p: p + (len(out)-len(inp))]
print('gap',p,'insertion',I,len(I))
gap=p
left_tm={}; right_tm={}
for N in range(15,46):
    left_tm[N]=oligotm(inp[gap-N:gap])
for M in range(15,46):
    right_tm[M]=oligotm(inp[gap:gap+M])
valid=[]
for N in left_tm:
    for M in right_tm:
        if 58<=left_tm[N]<=72 and 58<=right_tm[M]<=72 and abs(left_tm[N]-right_tm[M])<=5:
